const ld = require('lodash');
let responseData;
const contentType = pm.response.headers.get('Content-Type');
if (contentType === "application/xml") {
  var parseString = require('xml2js').parseString;
  parseString(pm.response.body, function(err, result) {
    if (err) {
      console.error('Error parsing XML:', err);
    } else {
      responseData = result;
    }
  });
} else {
  responseData = pm.response.json();
}
// Status code check with early exit
const expectedStatusCode = parseInt(pm.variables.get("statusCode"));
let statusMatches = true;
if (pm.variables.get("statusCode")) {
  statusMatches = (pm.response.code === expectedStatusCode);
  pm.test("Status code matches expected value", function() {
    pm.expect(pm.response.code).to.equal(expectedStatusCode);
  });
}

if (pm.response.code == 200 && statusMatches) {
  pm.test("The account contract identifier has been fetched successfully.", function() {
    pm.expect(pm.response.status).to.be.eql("OK");
  });

}
if (pm.response.code == 400 && statusMatches) {
  pm.test("The server cannot process the request due to bad request.", function() {
    pm.expect(pm.response.status).to.be.eql("Bad Request");
  });

}
if (pm.response.code == 403 && statusMatches) {
  pm.test("You do not have the permission to do this operation.", function() {
    pm.expect(pm.response.status).to.be.eql("Forbidden");
  });

}
if (pm.response.code == 404 && statusMatches) {
  pm.test("The URI did not match an existing resource.", function() {
    pm.expect(pm.response.status).to.be.eql("Not Found");
  });

}
if (pm.response.code == 409 && statusMatches) {
  pm.test("Original request with the same Idempotency key has not been processed yet.", function() {
    pm.expect(pm.response.status).to.be.eql("Conflict");
  });

}
if (pm.response.code == 422 && statusMatches) {
  pm.test("Idempotency key has been used in the last 24 hours.", function() {
    pm.expect(pm.response.status).to.be.eql("Unprocessable Entity (WebDAV) (RFC 4918)");
  });

}

